// In a notebook, do not edit this file. It is generic - the template's, listed
// in .claude/notebook/manifest.txt - and the update skill replaces it; the
// notebook's pre-commit hook refuses a commit that changes it. Its settings
// are data.json beside it, which the notebook owns; a fix every notebook
// needs is asked of the template, with an issue (.claude/notebook/requests.md).
// Notebook graph - part of the notebook-template system (.claude/notebook/graph.md,
// "Seeing it"). Obsidian gives a local graph no default settings: each pane keeps its
// own, starting with no colour groups. The notebook derives the global graph's colour
// groups and filter from its type declarations (`graph` in the notebook's script), so
// this copies them into every local graph as it opens, and again whenever they change.
// Only colorGroups and search are copied each time. A local graph also starts from the
// notebook's own local defaults - depth, forces, display - in this plugin's data.json
// ("localDefaults"), applied once, to a pane opened fresh (one with no colour groups
// yet); after that its settings are the user's, and a pane restored after a restart
// keeps them. Nothing global can set these: Obsidian has no local-graph default.
//
// It uses the graph plugin's internal options and the local graph view's state, which
// are not a public API - tested on Obsidian 1.14.4. If an update breaks it, local graphs
// simply go back to uncoloured; nothing else depends on it.
const { Plugin } = require("obsidian");

module.exports = class NotebookGraph extends Plugin {
  async onload() {
    this.settings = Object.assign({ localDefaults: {} }, await this.loadData());
    this.registerEvent(this.app.workspace.on("layout-change", () => this.syncAll()));
    this.registerEvent(this.app.workspace.on("active-leaf-change", () => this.syncAll()));
    this.addCommand({ id: "sync-local-graphs", name: "Give local graphs the global graph's groups",
                      callback: () => this.syncAll(true) });
    this.app.workspace.onLayoutReady(() => this.syncAll());
  }

  globalOptions() {
    const g = this.app.internalPlugins.getPluginById("graph");
    return g && g.enabled && g.instance ? g.instance.options : null;
  }

  syncAll(force = false) {
    const g = this.globalOptions();
    if (!g) return 0;
    let n = 0;
    for (const leaf of this.app.workspace.getLeavesOfType("localgraph")) {
      if (this.sync(leaf.view, g, force)) n++;
    }
    return n;
  }

  sync(view, g, force) {
    if (!view || !view.getState) return false;
    const state = view.getState();
    const o = state.options || {};
    const fresh = !(o.colorGroups && o.colorGroups.length);
    if (fresh) Object.assign(o, this.settings.localDefaults || {});
    const want = JSON.stringify([g.colorGroups || [], g.search || ""]);
    if (!force && !fresh && JSON.stringify([o.colorGroups || [], o.search || ""]) === want) return false;
    o.colorGroups = JSON.parse(JSON.stringify(g.colorGroups || []));
    o.search = g.search || "";
    state.options = o;
    view.setState(state, { history: false });
    const e = view.engine || view.dataEngine;
    if (e && e.setOptions) e.setOptions(Object.assign({}, e.getOptions(), o));
    if (view.onOptionsChange) view.onOptionsChange();
    return true;
  }
};
